<?php

namespace GraphQL\SchemaObject;

use GraphQL\Mutation;

/**
 * An abstract class that acts as the base for the root mutation object generated by the SchemaClassGenerator.
 * Selectors work exactly like they do on query objects, but the operation is sent as a mutation.
 *
 * Class MutationObject
 *
 * @package GraphQL\SchemaObject
 */
abstract class MutationObject extends QueryObject
{
    /**
     * This constant stores the name to be given to the root mutation object
     *
     * @var string
     */
    public const ROOT_MUTATION_OBJECT_NAME = 'RootMutation';

    /**
     * MutationObject constructor.
     *
     * @param string $fieldName
     */
    public function __construct(string $fieldName = '')
    {
        parent::__construct($fieldName);
        $this->query = new Mutation(!empty($fieldName) ? $fieldName : static::OBJECT_NAME);
    }

    /**
     * Synonymous method to getQuery(), it just returns a Mutation type instead of Query type
     *
     * @return Mutation
     */
    public function getMutation(): Mutation
    {
        return $this->getQuery();
    }
}
